import type { KillTeam } from "../core/killTeamTypes.ts";

// Every JSON file in ./killteams is a kill team (generated by
// `npm run import-killteams`, or hand-written). Each one shows up in the
// shooting helper's team dropdown, sorted by name.
const modules = import.meta.glob<KillTeam>("./killteams/*.json", { eager: true, import: "default" });

export const killTeams: KillTeam[] = Object.values(modules).sort((a, b) => a.name.localeCompare(b.name, "fr"));

export function getKillTeam(id: string | undefined): KillTeam | undefined {
  return killTeams.find((t) => t.id === id);
}
